using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9: ZipArchiveEntry now respects the UTF-8 flag in the entry header.
        // Our legacy Java consumer expects Shift-JIS filenames, so we must use the
        // ZipFile.Open overload with an explicit non-UTF8 encoding to prevent the
        // UTF-8 flag from being set in entries.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding(932)
                       ?? Encoding.UTF8;
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path encoded as Shift-JIS
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

